import{_ as n,C as s,o as e,c as d,j as i,a as r,E as t,a2 as l}from"./chunks/framework.C21TwvGF.js";const A=JSON.parse(`{"title":"1-dars (Mentor). Zamonaviy kompyuterlar va ularning arxitekturasi","description":"","frontmatter":{"title":"1-dars (Mentor). Zamonaviy kompyuterlar va ularning arxitekturasi","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"week":{"n":1,"link":"/mentor/8-sinf-cs/hafta-01/"},"g":1,"title":"Zamonaviy kompyuterlar va ularning arxitekturasi","lead":"Har kuni foydalanadigan kompyuteringiz aslida qanday ishlaydi? Ushbu darsda kompyuterning «ichki dunyosi»ga sayohat qilamiz: protsessor, tezkor xotira, fon Neyman arxitekturasi va kompyuterning yashirin texnik parametrlarini ochishni o'rganamiz.","slide":"/slaydlar/8-sinf-cs/hafta-01/dars-1.html","test":"/slaydlar/8-sinf-cs/hafta-01/dars-1-test.html","student_link":"/8-sinf-cs/hafta-01/dars-1","tabs":[{"g":1,"link":"/mentor/8-sinf-cs/hafta-01/dars-1","current":true},{"g":2,"link":"/mentor/8-sinf-cs/hafta-01/dars-2","current":false},{"g":3,"link":"/mentor/8-sinf-cs/hafta-01/dars-3","current":false}],"prev":null,"next":{"g":2,"title":"Operatsion tizimlar va Windows muhitida ishlash","link":"/mentor/8-sinf-cs/hafta-01/dars-2"}}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-01/dars-1.md","filePath":"mentor/8-sinf-cs/hafta-01/dars-1.md"}`),m={name:"mentor/8-sinf-cs/hafta-01/dars-1.md"},u={class:"blk"},h={id:"_1-dars-rejasi",tabindex:"-1"},k={class:"blk"},y={id:"_2-dars-konspekti",tabindex:"-1"},g={class:"blk"},p={id:"_3-kod-amaliy-namuna",tabindex:"-1"},v={class:"blk"},c={id:"_4-amaliy-topshiriqlar",tabindex:"-1"},b={class:"blk"},q={id:"_5-tezkor-nazorat",tabindex:"-1"},f={class:"blk"},z={id:"_6-uyga-vazifa",tabindex:"-1"};function x(_,a,S,D,M,P){const o=s("Icon");return e(),d("div",null,[a[19]||(a[19]=i("p",null,[i("strong",null,"Hafta:"),r(" 1 · "),i("strong",null,"Davomiyligi:"),r(" 80 daqiqa · "),i("strong",null,"Turi:"),r(" nazariya + ko'rgazmali amaliyot · "),i("strong",null,"I-bob"),r(", 1-dars")],-1)),i("div",u,[i("h2",h,[t(o,{name:"file-text"}),a[0]||(a[0]=r(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=l('<p><strong>Maqsad:</strong> o&#39;quvchilarda zamonaviy kompyuterlar turlari, fon Neyman tamoyili asosidagi kompyuter arxitekturasi, asosiy va qo&#39;shimcha qurilmalar, protsessor, xotira turlari (RAM, ROM, SSD/HDD) hamda kompyuterning ishlash tamoyili bo&#39;yicha mustahkam fundamental tushunchalarni shakllantirish.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>Kompyuter turlarini (statsionar, noutbuk, monoblok, server, superkompyuter) farqlay oladi va vazifasini tushuntiradi.</li><li>Kompyuter arxitekturasining asosiy qismlarini (protsessor, xotira, kiritish-chiqarish qurilmalari, shinalar) sxematik ifodalaydi.</li><li>CPU (takt chastotasi, yadrolar soni), RAM va doimiy xotira (SSD/HDD) farqini va ularning kompyuter tezligiga ta&#39;sirini biladi.</li><li>Windows operatsion tizimida kompyuterning texnik ko&#39;rsatkichlarini (protsessor modeli, RAM hajmi, disk turi) mustaqil aniqlay oladi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–5 daq</td><td>Tanishuv va kirish</td><td>O&#39;quvchilar bilan tanishuv, «Computer Science Foundation» kursi maqsadi va qoidalari</td></tr><tr><td>5–25 daq</td><td>Yangi mavzu: Nazariya</td><td>Kompyuter turlari, arxitekturasi (fon Neyman modeli), CPU, RAM, ROM, SSD/HDD, shinalar</td></tr><tr><td>25–30 daq</td><td>Savol-javob va muhokama</td><td>«Nega kompyuter o&#39;chganda ochilgan dasturlar yopiladi?», «RAM va SSD farqi nima?»</td></tr><tr><td>30–35 daq</td><td>Tanaffus</td><td>Ko&#39;z va tana mashqlari</td></tr><tr><td>35–65 daq</td><td>Amaliy mashg&#39;ulot</td><td>Kompyuter texnik ko&#39;rsatkichlarini aniqlash (Task Manager, msinfo32, dxdiag)</td></tr><tr><td>65–75 daq</td><td>Tezkor nazorat</td><td>5 ta test/savol orqali bilimlarni tekshirish</td></tr><tr><td>75–80 daq</td><td>Xulosa va uyga vazifa</td><td>Asosiy xulosalar va uy vazifasini tushuntirish</td></tr></tbody></table><hr>',5))]),i("div",k,[i("h2",y,[t(o,{name:"file-text"}),a[3]||(a[3]=r(" 2. Dars konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-dars-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars konspekti"'},"​",-1))]),a[5]||(a[5]=l('<h3 id="_2-1-zamonaviy-kompyuterlar-va-ularning-turlari" tabindex="-1">2.1. Zamonaviy kompyuterlar va ularning turlari <a class="header-anchor" href="#_2-1-zamonaviy-kompyuterlar-va-ularning-turlari" aria-label="Permalink to &quot;2.1. Zamonaviy kompyuterlar va ularning turlari&quot;">​</a></h3><p><strong>Kompyuter</strong> — axborotni qabul qilish, saqlash, qayta ishlash va foydalanuvchiga qulay ko&#39;rinishda chiqarib berish uchun mo&#39;ljallangan universal elektron hisoblash mashinasi.</p><p>Zamonaviy kompyuterlar vazifasi va o&#39;lchamiga ko&#39;ra quyidagi turlarga bo&#39;linadi:</p><ol><li><strong>Statsionar kompyuter (Desktop PC):</strong> Ish stoli uchun mo&#39;ljallangan, tizim bloki, monitor, klaviatura va sichqoncha alohida bloklardan iborat bo&#39;ladi. Quvvati yuqori, qismlarini yangilash (upgrade) oson.</li><li><strong>Noutbuk (Laptop):</strong> Barcha qurilmalari (ekran, klaviatura, touchpad, batareya) bitta ixcham korpusda jamlangan, ko&#39;chma kompyuter.</li><li><strong>Monoblok (All-in-One):</strong> Tizim bloki va monitor bitta umumiy korpusda birlashtirilgan kompyuter.</li><li><strong>Server:</strong> Tarmoqdagi yuzlab yoki millionlab foydalanuvchilarga doimiy xizmat ko&#39;rsatuvchi, 24/7 rejimida to&#39;xtovsiz ishlaydigan kuchli kompyuter.</li><li><strong>Superkompyuter:</strong> Sekundiga kvadtrillionlab murakkab matematik hisob-kitoblarni bajaradigan, ob-havo bashorati, kosmik tadqiqotlar va sun&#39;iy intellekt modellarini o&#39;rgatish uchun ishlatiladigan ulkan hisoblash tizimlari.</li></ol><h3 id="_2-2-kompyuter-arxitekturasi-va-fon-neyman-tamoyili" tabindex="-1">2.2. Kompyuter arxitekturasi va fon Neyman tamoyili <a class="header-anchor" href="#_2-2-kompyuter-arxitekturasi-va-fon-neyman-tamoyili" aria-label="Permalink to &quot;2.2. Kompyuter arxitekturasi va fon Neyman tamoyili&quot;">​</a></h3><p>1945-yilda mashhur olim Jon fon Neyman tomonidan taklif etilgan tamoyilga ko&#39;ra, har qanday zamonaviy kompyuter quyidagi 4 ta asosiy qismdan tashkil topadi:</p><ol><li><strong>Aрифметик-mantiqiy qurilma va boshqaruv qurilmasi (CPU — Markaziy protsessor):</strong> Barcha hisoblashlar va boshqaruvni amalga oshiradi.</li><li><strong>Xotira qurilmasi:</strong> Dastur va ma&#39;lumotlarni saqlash joyi (Ichki: RAM/ROM, Tashqi: SSD/HDD).</li><li><strong>Kiritish qurilmalari:</strong> Ma&#39;lumotlarni kompyuterga kiritish (klaviatura, sichqoncha, mikrofon, skaner).</li><li><strong>Chiqarish qurilmalari:</strong> Natijalarni foydalanuvchiga taqdim etish (monitor, printer, dinamiklar).</li></ol><p>Ushbu qismlar o&#39;zaro <strong>tizimli shina (System Bus)</strong> orqali bog&#39;langan bo&#39;lib, ular orqali ma&#39;lumotlar, manzillar va boshqaruv signallari harakatlanadi.</p><h3 id="_2-3-tizim-blokining-asosiy-komponentlari" tabindex="-1">2.3. Tizim blokining asosiy komponentlari <a class="header-anchor" href="#_2-3-tizim-blokining-asosiy-komponentlari" aria-label="Permalink to &quot;2.3. Tizim blokining asosiy komponentlari&quot;">​</a></h3><ul><li><strong>Ona plata (Motherboard):</strong> Barcha komponentlarni (CPU, RAM, videokarta, xotira disklari) o&#39;zaro elektr va axborot magistrallari orqali bog&#39;lovchi bosh elektron plata.</li><li><strong>Markaziy protsessor (CPU — Central Processing Unit):</strong> Kompyuterning «miyasi». U dastur buyruqlarini bajaradi. Asosiy ko&#39;rsatkichlari: <ul><li><em>Takt chastotasi (GHz):</em> Protsessor bir sekundda bajara oladigan operatsiyalar soni (masalan, 3.2 GHz = sekundiga 3.2 milliard takt).</li><li><em>Yadrolar soni (Cores):</em> Bir vaqtning o&#39;zida parallel bajariladigan ishlar soni (2, 4, 8, 16 yadro).</li></ul></li><li><strong>Tezkor xotira (RAM — Random Access Memory):</strong> Kompyuter ishlab turganda joriy dasturlar va ma&#39;lumotlarni vaqtincha saqlovchi juda tezkor xotira. Kompyuter o&#39;chirilganda RAM&#39;dagi barcha ma&#39;lumotlar o&#39;chib ketadi (uchuvchan xotira).</li><li><strong>Doimiy xotira (ROM — Read Only Memory):</strong> Kompyuterni yoqish uchun zarur bo&#39;lgan dastlabki tizim dasturlarini (BIOS/UEFI) saqlovchi xotira. Faqat o&#39;qish uchun mo&#39;ljallangan, o&#39;chib ketmaydi.</li><li><strong>Ma&#39;lumotlarni saqlash disklari (HDD va SSD):</strong><ul><li><em>HDD (Hard Disk Drive):</em> Magnitli aylanuvchi disklarga asoslangan an&#39;anaviy xotira. Sig&#39;imi katta, lekin tezligi sekinroq (100–150 MB/s).</li><li><em>SSD (Solid State Drive):</em> Mikrochiplar (flesh-xotira) asosidagi zamonaviy xotira. Mexanik harakatlanuvchi qismlari yo&#39;q, ovozsiz va HDD dan 5–30 baravar tezroq (500–5000+ MB/s).</li></ul></li><li><strong>Videokarta (GPU — Graphics Processing Unit):</strong> Grafik tasvirlar, animatsiyalar, videolar va 3D grafikalarni qayta ishlovchi va monitorga chiqaruvchi qurilma.</li><li><strong>Quvvat ta&#39;minoti bloki (Power Supply Unit — PSU):</strong> 220V o&#39;zgaruvchan tokni kompyuter qismlari uchun zarur bo&#39;lgan doimiy 12V, 5V, 3.3V kuchlanishlarga aylantirib beruvchi blok.</li></ul><hr>',11))]),i("div",g,[i("h2",p,[t(o,{name:"file-text"}),a[6]||(a[6]=r(" 3. Kod / Amaliy namuna ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-kod-amaliy-namuna","aria-label":'Permalink to "<Icon name="file-text" /> 3. Kod / Amaliy namuna"'},"​",-1))]),a[8]||(a[8]=l('<p>Kompyuterning texnik parametrlarini bilish dasturchi va IT mutaxassisi uchun muhim ko&#39;nikmadir. Windows muhitida buni 3 ta asosiy usulda ko&#39;rish mumkin:</p><h3 id="_1-usul-vazifalar-boshqaruvchisi-task-manager" tabindex="-1">1-usul: Vazifalar boshqaruvchisi (Task Manager) <a class="header-anchor" href="#_1-usul-vazifalar-boshqaruvchisi-task-manager" aria-label="Permalink to &quot;1-usul: Vazifalar boshqaruvchisi (Task Manager)&quot;">​</a></h3><ol><li>Klaviaturada <code>Ctrl + Shift + Esc</code> tugmalarini bosing.</li><li>«Performance» (Samaradorlik) bo&#39;limiga o&#39;ting.</li><li>CPU, Memory (RAM), Disk (SSD/HDD), Wi-Fi va GPU parametrlarini kuzating.</li></ol><h3 id="_2-usul-tizim-ma-lumotlari-oynasi-msinfo32" tabindex="-1">2-usul: Tizim ma&#39;lumotlari oynasi (msinfo32) <a class="header-anchor" href="#_2-usul-tizim-ma-lumotlari-oynasi-msinfo32" aria-label="Permalink to &quot;2-usul: Tizim ma&#39;lumotlari oynasi (msinfo32)&quot;">​</a></h3><ol><li><code>Win + R</code> tugmalarini bosib, «Run» (Bajarish) darchasini oching.</li><li><code>msinfo32</code> deb yozing va <code>Enter</code> bosing.</li><li>«System Summary» bo&#39;limida protsessor modeli, BIOS versiyasi, operativ xotira hajmi va tizim turi ko&#39;rinadi.</li></ol><h3 id="_3-usul-directx-diagnostika-vositasi-dxdiag" tabindex="-1">3-usul: DirectX diagnostika vositasi (dxdiag) <a class="header-anchor" href="#_3-usul-directx-diagnostika-vositasi-dxdiag" aria-label="Permalink to &quot;3-usul: DirectX diagnostika vositasi (dxdiag)&quot;">​</a></h3><ol><li><code>Win + R</code> bosing, <code>dxdiag</code> deb yozing va <code>Enter</code> bosing.</li><li>Tizim va Displey bo&#39;limlaridan videokarta va protsessor haqida to&#39;liq hisobotni ko&#39;ring.</li></ol><hr>',8))]),i("div",v,[i("h2",c,[t(o,{name:"file-text"}),a[9]||(a[9]=r(" 4. Amaliy topshiriqlar ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-amaliy-topshiriqlar","aria-label":'Permalink to "<Icon name="file-text" /> 4. Amaliy topshiriqlar"'},"​",-1))]),a[11]||(a[11]=l('<h3 id="_1-topshiriq-oson" tabindex="-1">1-topshiriq (oson) <a class="header-anchor" href="#_1-topshiriq-oson" aria-label="Permalink to &quot;1-topshiriq (oson)&quot;">​</a></h3><p>O&#39;zingiz o&#39;tirgan kompyuterda <code>Ctrl + Shift + Esc</code> orqali Task Manager dasturini oching. Protsessorning (CPU) nomini, uning joriy ish chastotasini va kompyuterdagi jami RAM (operativ xotira) hajmini aniqlang.</p><p><strong>Kutiladigan natija:</strong> Protsessor nomi (masalan, Intel Core i5-11400 yoki AMD Ryzen 5 5600G) va RAM hajmi (masalan, 8 GB yoki 16 GB) daftarga yoziladi.</p><p><strong>Yechim:</strong></p><ol><li>Klaviaturada <code>Ctrl + Shift + Esc</code> birgalikda bosiladi.</li><li>Chap yoki yuqori menyudan ikkinchi belgi — «Performance» (Samaradorlik) tanlanadi.</li><li>«CPU» tanlanganda o&#39;ng yuqori burchakda protsessorning aniq modeli va pastda yadrolar soni (Cores/Logical processors) ko&#39;rinadi.</li><li>«Memory» tanlanganda o&#39;ng yuqori qismda jami RAM hajmi (masalan, <code>8.0 GB DDR4</code>) ko&#39;rinadi.</li></ol><hr><h3 id="_2-topshiriq-o-rta" tabindex="-1">2-topshiriq (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-o-rta" aria-label="Permalink to &quot;2-topshiriq (o&#39;rta)&quot;">​</a></h3><p><code>Win + R</code> orqali <code>msinfo32</code> darchasini oching. Quyidagi 4 ta ma&#39;lumotni toping va yozib oling:</p><ol><li>Operatsion tizim nomi (OS Name).</li><li>Tizim turi (System Type: 64-bit yoki 32-bit).</li><li>Protsessorning yadrolari soni (Cores).</li><li>O&#39;rnatilgan jismoniy xotira (Installed Physical Memory / RAM).</li></ol><p><strong>Kutiladigan natija:</strong> Jadval shaklida 4 ta parametr aniq yoziladi.</p><p><strong>Yechim:</strong></p><ol><li><code>Win + R</code> bosiladi, ochilgan darchaga <code>msinfo32</code> yoziladi va <code>Enter</code> bosiladi.</li><li>«System Summary» ro&#39;yxatidan qidiriladi: <ul><li>OS Name: Masalan, <em>Microsoft Windows 11 Pro</em> yoki <em>Windows 10 Enterprise</em>.</li><li>System Type: <em>x64-based PC</em>.</li><li>Processor: Masalan, <em>11th Gen Intel(R) Core(TM) i5-1135G7 @ 2.40GHz, 4 Core(s), 8 Logical Processor(s)</em>.</li><li>Installed Physical Memory (RAM): Masalan, <em>8.00 GB</em>.</li></ul></li></ol><hr><h3 id="_3-topshiriq-qiyin" tabindex="-1">3-topshiriq (qiyin) <a class="header-anchor" href="#_3-topshiriq-qiyin" aria-label="Permalink to &quot;3-topshiriq (qiyin)&quot;">​</a></h3><p>Kompyuter xotira diskining turi (SSD yoki HDD) va bo&#39;sh joyini aniqlang. Nima uchun zamonaviy dasturlashda HDD o&#39;rniga SSD tavsiya etilishini texnik jihatdan asoslab bering.</p><p><strong>Kutiladigan natija:</strong> Disk turi va hajmi ko&#39;rsatiladi; SSD ning HDD dan 3 ta asosiy ustunligi (tezlik, shovqinsizlik, ishonchlilik) yoziladi.</p><p><strong>Yechim:</strong></p><ol><li>Task Manager dasturida «Performance» → «Disk 0» bo&#39;limiga kiriladi. U yerda disk turi ko&#39;rsatilgan: masalan, <code>SSD</code> yoki <code>HDD</code>.</li><li>Model nomi (masalan, NVMe Kingston 512GB) va uning hajmi ko&#39;rinadi.</li><li>Asoslash: <ul><li>SSD da aylanuvchi magnit plastinka va harakatlanuvchi kallak yo&#39;q, u butunlay mikrochiplarda ishlaydi.</li><li>O&#39;qish/yozish tezligi: HDD da 100-150 MB/s bo&#39;lsa, NVMe SSD larda 2000-5000+ MB/s ga yetadi (20-30 baravar tez).</li><li>Dasturlarni kompilyatsiya qilish, fayllarni yuklash va operatsion tizimning yuklanishi bir necha soniyada amalga oshadi.</li></ul></li></ol><hr>',19))]),i("div",b,[i("h2",q,[t(o,{name:"file-text"}),a[12]||(a[12]=r(" 5. Tezkor nazorat ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#_5-tezkor-nazorat","aria-label":'Permalink to "<Icon name="file-text" /> 5. Tezkor nazorat"'},"​",-1))]),a[14]||(a[14]=l("<ol><li>Jon fon Neyman arxitekturasining 4 ta asosiy qismini sanab bering. <ul><li><em>Javob:</em> Markaziy protsessor (CPU), xotira (RAM/ROM/saqlash), kiritish qurilmalari, chiqarish qurilmalari.</li></ul></li><li>RAM va SSD xotiralarining eng asosiy farqi nimada? <ul><li><em>Javob:</em> RAM — vaqtinchalik va juda tezkor (kompyuter o&#39;chsa ma&#39;lumot yo&#39;qoladi); SSD — doimiy va ma&#39;lumotlarni yillar davomida saqlaydi.</li></ul></li><li>Protsessorning takt chastotasi (GHz) nimani bildiradi? <ul><li><em>Javob:</em> Protsessor bir sekundda bajara oladigan elektr impulslari (taktlari / amallari) sonini bildiradi. 1 GHz = 1 milliard takt/sekund.</li></ul></li><li>Kiritish va chiqarish qurilmalariga 3 tadan misol keltiring. <ul><li><em>Javob:</em> Kiritish: klaviatura, sichqoncha, mikrofon, skaner. Chiqarish: monitor, dinamik (kolonka), printer.</li></ul></li><li>Task Manager oynasini ochish uchun qaysi klavishlar kombinatsiyasi ishlatiladi? <ul><li><em>Javob:</em> <code>Ctrl + Shift + Esc</code> (yoki <code>Ctrl + Alt + Delete</code> orqali).</li></ul></li></ol><hr>",2))]),i("div",f,[i("h2",z,[t(o,{name:"file-text"}),a[15]||(a[15]=r(" 6. Uyga vazifa ",-1)),a[16]||(a[16]=i("a",{class:"header-anchor",href:"#_6-uyga-vazifa","aria-label":'Permalink to "<Icon name="file-text" /> 6. Uyga vazifa"'},"​",-1))]),a[17]||(a[17]=i("p",null,"Uyda yoki maktab kompyuterida o'z kompyuteringiz parametrlarini aniqlang va quyidagi jadvalni daftarga to'ldiring:",-1)),a[18]||(a[18]=i("ol",null,[i("li",null,"Kompyuter turi (statsionar, noutbuk yoki monoblok)."),i("li",null,"Protsessor modeli va takt chastotasi."),i("li",null,"Operativ xotira (RAM) hajmi."),i("li",null,"Doimiy xotira turi (HDD yoki SSD) va umumiy sig'imi."),i("li",null,"Kompyuteringizga ulangan 2 ta kiritish va 2 ta chiqarish qurilmasi nomi. Vazifani bajarish vaqti: 20 daqiqa.")],-1))])])}const j=n(m,[["render",x]]);export{A as __pageData,j as default};
